from uuid import UUID

import pytest

from bench.language import (
    EnumType,
    Field,
    NodeReference,
    NodeType,
    PrimitiveType,
    Session,
    StructType,
    Type,
    TypeKind,
    decode_type_identity,
    encode_type_identity,
)

# the targets were generated by manually running and verifying encode_type_identity
TEST_TYPE_IDENTITIES: tuple[tuple[Type, str], ...] = (
    (Type(kind=TypeKind.PRIMITIVE, primitive_type=PrimitiveType.DATETIME), "pe"),
    (Type(kind=TypeKind.NODE, bench_type=NodeType.USER, is_list=True), "N"),
    (Type(kind=TypeKind.BASED_NODE, bench_type=NodeType.FIELD, is_list=True), "N"),
    (Type(kind=TypeKind.STRUCT, bench_type=StructType.TEXT), "sg7C"),
    (Type(kind=TypeKind.ENUM, bench_type=EnumType.OBJECT_TYPE, is_secret=True), "!ej4E"),
    (
        Type(
            kind=TypeKind.CUSTOM_OBJECT,
            base_type_ptr=NodeReference(
                node_type=NodeType.BLOCK,
                id=UUID("12345678-ffff-0000-0000-000000000000"),
                ck=UUID("12345678-ffff-0000-0000-000000000000"),
            ),
        ),
        "oAAAAAAAAAAAAA8//4ZFNS",
    ),
    (Type(kind=TypeKind.PARTIAL_OBJECT), "r"),
)


@pytest.mark.parametrize("target", TEST_TYPE_IDENTITIES)
def test_roundtrip_type_identity(target: tuple[Type, str]):
    type_info, target_key = target
    identity_key = encode_type_identity(type_info)
    assert identity_key and identity_key == target_key
    decoded = decode_type_identity(identity_key)
    assert decoded.primitive_type == type_info.primitive_type
    assert decoded.is_list == type_info.is_list
    assert decoded.is_secret == type_info.is_secret


def test_change_type_identity(session: Session):
    """Updating a Field's type should change its type identity."""
    Field1 = Field.member("Field1", str, is_list=False)
    old_type_identity = Field1.identity_key
    Field1.is_list = True
    assert Field1.identity_key != old_type_identity
